sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var util = new LeaveRequestUtils();
    var isAdmin = gs.hasRole('x_2236918_leavef_1.admin') || gs.hasRole('admin');

    // A cancelled request is final (stops a late approval from reviving it)
    if (!current.isNewRecord() && previous.status == 'cancelled' && current.status != 'cancelled') {
        gs.addErrorMessage('A cancelled request cannot be reopened.');
        current.setAbortAction(true);
        return;
    }
    // 1. Employee is always the signed-in user, unless an admin files on behalf of someone
    if (current.isNewRecord() && !isAdmin) {
        current.employee = gs.getUserID();
    }
    // 2. Manager comes from the employee profile; an admin may override
    if (current.manager.nil() || (current.employee.changes() && !isAdmin)) {
        current.manager = current.employee.manager;
    }
    if (!current.manager.nil() && current.manager == current.employee) {
        gs.addErrorMessage('An employee cannot be their own approver.');
        current.setAbortAction(true);
        return;
    }
    // 3. Date range check (server-side, independent of any client script)
    var result = util.validateRange(current.getValue('start_date'), current.getValue('end_date'));
    if (!result.valid) {
        gs.addErrorMessage(result.message);
        current.setAbortAction(true);
        return;
    }
    current.days_requested = result.days;
    // 4. After the first save, non-admins may not change core fields
    if (!current.isNewRecord() && previous.status != 'draft' && !isAdmin) {
        var locked = ['employee', 'manager', 'leave_type', 'start_date', 'end_date', 'reason'];
        for (var i = 0; i < locked.length; i++) {
            if (current[locked[i]].changes()) {
                gs.addErrorMessage('A submitted request cannot be edited. Cancel it and create a new one.');
                current.setAbortAction(true);
                return;
            }
        }
    }
    // 5. Extra rules only at the moment of submission
    var submitting = current.status == 'submitted' &&
        (current.isNewRecord() || current.status.changes());
    if (submitting) {
        if (current.manager.nil()) {
            gs.addErrorMessage('You have no manager on your profile. Ask an administrator to set one.');
            current.setAbortAction(true);
            return;
        }
        if (util.hasOverlap(current.getValue('employee'), current.getValue('start_date'),
                current.getValue('end_date'), current.getUniqueValue())) {
            gs.addErrorMessage('You already have leave requested or approved that overlaps these dates.');
            current.setAbortAction(true);
            return;
        }
        if (current.leave_type.active.toString() !== 'true') {
            gs.addErrorMessage('The selected leave type is no longer active.');
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
